mod file_versions;

#[cfg(test)]
mod perf_probe {
    use super::*;
    #[test]
    #[ignore]
    fn save_backend_comparison() {
        let roots: Vec<_>=(0..3).map(|_| tempfile::tempdir().unwrap()).collect();
        let paths: Vec<_>=roots.iter().map(|r| r.path().join("save-probe.typ")).collect();
        let mut source=vec![b'a';128*1024];
        for path in &paths {std::fs::write(path,&source).unwrap();}
        println!("profile=release fixture=128KiB warmup=5 samples=15 measured=10 workload=changed-tail disk=temporary-local");
        println!("mode,sample,elapsed_us");
        for sample in 0..15 {
            source[128*1024-1]=b'A'+sample;
            for (mode,path) in paths.iter().enumerate() {
                let started=std::time::Instant::now();
                match mode {
                    0=> {private_workspace::AtomicFileWriter::write(path,&source).unwrap();},
                    1=> {let (_,warning)=file_versions::write_checked(path,&source,save_transaction::SaveIntent::Auto,||Ok(())).unwrap();assert!(warning.is_none());},
                    _=> {let (_,warning)=file_versions::write_checked(path,&source,save_transaction::SaveIntent::Explicit,||Ok(())).unwrap();assert!(warning.is_none());},
                }
                println!("{mode},{sample},{}",started.elapsed().as_micros());
            }
        }
        println!("auto_revisions={} explicit_revisions={}",file_versions::list(&paths[1]).unwrap().len(),file_versions::list(&paths[2]).unwrap().len());
    }
}
